diff --git a/src/bff/post-form/aws/fetchAWSApiEndpoint.ts b/src/bff/post-form/aws/fetchAWSApiEndpoint.ts
new file mode 100644
index 0000000..fc927cd
--- /dev/null
+++ b/src/bff/post-form/aws/fetchAWSApiEndpoint.ts
@@ -0,0 +1,82 @@
+import path from 'path';
+import axios from 'axios';
+import {getApiEndpoint, getApiHeaders} from '../../utils/api-endpoint';
+import type {Configuration} from '../config';
+import type {
+  APIEndpoints,
+  IAPIBadResponse,
+  IAPIResponse,
+  IAPIResponseData,
+  MulesoftRequestTypesMap,
+} from './types';
+import {isValidAPIResponse} from './types';
+
+type FetchAWSApiEndpointParams<E extends APIEndpoints> = {
+  configuration: Configuration;
+  envName: string;
+  data: MulesoftRequestTypesMap[E];
+  endpointName: E;
+  method: 'POST' | 'PUT';
+  sessionToken?: string;
+  campaignId?: string;
+  leadsource?: string;
+  salesChannel?: string;
+};
+
+export async function fetchAWSApiEndpoint<E extends APIEndpoints>(
+  params: FetchAWSApiEndpointParams<E>,
+): Promise<[true, IAPIResponseData] | [false, string]> {
+  const {
+    envName,
+    data,
+    endpointName,
+    method,
+    campaignId,
+    leadsource,
+    salesChannel,
+    sessionToken,
+  } = params;
+
+  const apiEndpoint = getApiEndpoint(envName);
+  const apiHeaders = getApiHeaders();
+
+  const finalUrl = new URL(path.posix.join(`${apiEndpoint}/v1`, endpointName));
+
+  const headers: Record<string, string> = {
+    ...apiHeaders,
+    'Content-Type': `application/json`,
+  };
+
+  if (leadsource) {
+    headers[`LeadSource`] = leadsource;
+  }
+  if (salesChannel) {
+    headers[`X-Channel`] = salesChannel;
+  }
+  if (campaignId) {
+    headers[`X-Campaign-id`] = campaignId;
+  }
+  if (sessionToken) {
+    headers[`Authorization`] = sessionToken;
+  }
+
+  try {
+    const response = await axios({
+      method,
+      headers,
+      url: finalUrl.href,
+      data,
+      maxRedirects: 5,
+      validateStatus: () => true,
+    });
+
+    const json = response.data as IAPIResponse | IAPIBadResponse;
+
+    if (isValidAPIResponse(json)) {
+      return [true, json[`response-data`]];
+    }
+    return [false, `server error`];
+  } catch (error) {
+    return [false, `server error`];
+  }
+}

