--- /dev/null
+++ b/stacks/AppConfig.ts
@@ -0,0 +1,46 @@
+import type {StackContext} from 'sst/constructs';
+import {Config} from 'sst/constructs';
+
+const featureLocalAppName = `esign-app`;
+export function AppConfig({stack, app}: StackContext) {
+  const featureAppName = new Config.Parameter(stack, `FEATURE_APP_NAME`, {
+    value: process.env.FEATURE_APP_NAME ?? featureLocalAppName,
+  });
+
+  const hostedZone = new Config.Parameter(stack, `AWS_HOSTED_ZONE_NAME`, {
+    value:
+      process.env.AWS_HOSTED_ZONE_NAME ??
+      `${stack.stage}.${featureLocalAppName}.feature-app.srv.smart.com`,
+  });
+
+  const endpointDirectoryApiKey = new Config.Parameter(
+    stack,
+    `ENDPOINT_DIRECTORY_API_KEY`,
+    {
+      value: process.env.ENDPOINT_DIRECTORY_API_KEY ?? ``,
+    },
+  );
+
+  const awsApiKey = new Config.Parameter(stack, `AWS_API_KEY`, {
+    value: process.env.AWS_API_KEY ?? ``,
+  });
+
+  const target = new Config.Parameter(stack, `TARGET`, {
+    value: process.env.TARGET ?? `dev`,
+  });
+
+  app.addDefaultFunctionBinding([
+    endpointDirectoryApiKey,
+    target,
+    featureAppName,
+    awsApiKey,
+  ]);
+
+  return {
+    hostedZone: hostedZone.value,
+    target: target.value,
+    featureAppName: featureAppName.value,
+    endpointDirectoryApiKey: endpointDirectoryApiKey.value,
+    awsApiKey: awsApiKey.value,
+  };
+}

diff --git a/stacks/BffApi.ts b/stacks/BffApi.ts
new file mode 100644
index 0000000..06c0fca
--- /dev/null
+++ b/stacks/BffApi.ts
@@ -0,0 +1,37 @@
+import type {StackContext} from 'sst/constructs';
+import {Api, use} from 'sst/constructs';
+import {AppConfig} from './AppConfig';
+
+export function BffApi({stack}: StackContext) {
+  const {hostedZone, target, featureAppName} = use(AppConfig);
+  const baseUrl = `/__app__/${featureAppName}/${target}`;
+  const privateBaseUrl = `/__app-private__/${featureAppName}/${target}`;
+  const api = new Api(stack, `api`, {
+    customDomain: {
+      hostedZone,
+      domainName: [`stage`, `dev`, `prod`].includes(stack.stage)
+        ? `bff.${hostedZone}`
+        : `bff.${stack.stage}.${hostedZone}`,
+    },
+    routes: {
+      [`GET ${baseUrl}/bff/app-model`]: {
+        function: {
+          handler: `src/bff/app-model/index.handler`,
+          functionName: `BffAppModelFunction-${stack.stage}`,
+          memorySize: 3072,
+        },
+      },
+      [`POST ${privateBaseUrl}/bff/post-form`]: {
+        function: {
+          handler: `src/bff/post-form/index.handler`,
+          functionName: `BffPostFormFunction-${stack.stage}`,
+          memorySize: 3072,
+        },
+      },
+    },
+  });
+  stack.addOutputs({
+    apiUrl: api.customDomainUrl ?? api.url,
+  });
+  return api;
+}

